{"command": "create", "path": "/app/workspace/extract_receipts_v2.py", "file_text": "#!/usr/bin/env python3
"""OCR-based extraction of date and total amount from receipt images."""
import datetime
import re
import sys
from collections import Counter
from pathlib import Path

import pytesseract
from PIL import Image, ImageFilter, ImageOps
from openpyxl import Workbook

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

# Keyword priorities (higher first). "TOTAL RM" variants included; inclusive-GST
# phrases like "Total Sales Inclusive of GST" are allowed to survive the GST
# exclusion filter.
TOTAL_KEYWORDS_PRIORITIZED = [
    (10, [r"GRAND\s*TOTAL", r"GRANDTOTAL"]),
    (9,  [r"TOTAL\s*[:;.]?\s*R[MN]\b", r"TOTAL\s*AMT\s*R[MN]"]),
    (8,  [r"TOTAL\s*AMOUNT", r"TOTAL\s*AMT\b"]),
    (7,  [r"NETT\s*TOTAL", r"NET\s*TOTAL"]),
    (6,  [r"TOTAL\s*DUE", r"AMOUNT\s*DUE", r"AMT\s*DUE",
          r"BALANCE\s*DUE"]),
    (5,  [r"TOTAL\s*SALES.*INCL", r"TOTAL.*INCL.*GST",
          r"TOTAL\s*INCL", r"TOTAL\s*ROUNDED", r"TOTAL\s*AFTER\s*ROUNDING"]),
    (4,  [r"\bTOTAL\b"]),
    (3,  [r"\bAMOUNT\b", r"\bAMT\b"]),
]

EXCLUDE_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL",
    "TAX", "GST", "SST",
    "DISCOUNT", "CHANGE",
    "CASH TENDERED", "CASH RECEIVED",
    "TOTAL ITEM", "TOTAL ITEMS", "ITEM COUNT", "TOTAL QTY",
    "EXCLUDING", "EXCL",
    "TOTAL SAVINGS",
    "TAXABLE",
    "TOTAL QTY TENDER",
]

MONEY_RE = re.compile(r"(?<![\d.])\d{1,3}(?:,\d{3})*\.\d{2}(?!\d)|(?<![\d.])\d+\.\d{2}(?!\d)")

DATE_LABEL_RE = re.compile(
    r"\b(DATE|DATED|DAtE|DAIE|DATA|DOC\s*DATE|INVOICE\s*DATE|TAX\s*DATE|SALES\s*DATE)\b\s*[:#]?",
    re.IGNORECASE,
)

DATE_PATTERNS = [
    re.compile(r"\b(\d{1,2})[/\-.~](\d{1,2})[/\-.~](\d{2}|\d{4})\b"),
    re.compile(r"\b(\d{4})[/\-.~](\d{1,2})[/\-.~](\d{1,2})\b"),
]

# Textual months: "28 Mar 18", "28 Mar 2018"
MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
}
MONTH_DATE_RE = re.compile(
    r"\b(\d{1,2})\s+(" + "|".join(MONTHS.keys()) + r")[a-z]*\s+(\d{2}|\d{4})\b",
    re.IGNORECASE,
)


# ---------------- OCR passes ----------------
def ocr_passes(img):
    texts = []
    texts.append(("raw", pytesseract.image_to_string(img, lang="eng")))
    g = ImageOps.grayscale(img)
    gc = ImageOps.autocontrast(g)
    for psm in ("--psm 6", "--psm 4", "--psm 11"):
        texts.append((f"gc {psm}", pytesseract.image_to_string(gc, lang="eng", config=psm)))
    sharp = gc.filter(ImageFilter.SHARPEN)
    texts.append(("sharp psm6", pytesseract.image_to_string(sharp, lang="eng", config="--psm 6")))
    if min(img.size) < 1200:
        big2 = img.resize((img.size[0] * 2, img.size[1] * 2))
        big2 = ImageOps.autocontrast(ImageOps.grayscale(big2))
        texts.append(("2x psm6", pytesseract.image_to_string(big2, lang="eng", config="--psm 6")))
        texts.append(("2x psm4", pytesseract.image_to_string(big2, lang="eng", config="--psm 4")))
    return [(lbl, t) for lbl, t in texts if t and t.strip()]


# ---------------- Text normalization ----------------
def normalize_number_spaces(line):
    """Fix OCR artefacts like '49. 40' -> '49.40' or '49, 40' -> '49.40'."""
    out = re.sub(r"(\d)\s*[,.]\s+(\d{2})\b", r"\1.\2", line)
    # Period with no space but comma already handled; now unify remaining commas
    # that look like decimals: e.g. '49,40' at end of token
    return out


# ---------------- Date extraction ----------------
def _try_date(d, m, y):
    try:
        d, m, y = int(d), int(m), int(y)
    except (ValueError, TypeError):
        return None
    if y < 100:
        y += 2000 if y < 50 else 1900
    if not (1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2030):
        return None
    try:
        datetime.date(y, m, d)
    except ValueError:
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


# Common OCR digit confusions used only for lenient date recovery.
_CONFUSIONS = {"0": ["0", "8", "9", "6"], "1": ["1", "7"], "2": ["2"],
               "3": ["3", "8"], "5": ["5", "6", "8"], "7": ["7", "1"],
               "8": ["8", "0", "3"], "9": ["9", "0"], "4": ["4"], "6": ["6"]}


def _lenient_fix(part, is_year=False):
    """Yield plausible corrections for a numeric token (OCR digit swaps)."""
    yield part
    # Try single-digit substitutions
    for i, ch in enumerate(part):
        for repl in _CONFUSIONS.get(ch, []):
            if repl != ch:
                yield part[:i] + repl + part[i + 1:]


def find_dates_in_line(line):
    out = []
    # Textual month format
    for m in MONTH_DATE_RE.finditer(line):
        d, mon_str, y = m.group(1), m.group(2), m.group(3)
        iso = _try_date(d, MONTHS[mon_str.lower()], y)
        if iso:
            out.append((iso, True))
    for pat in DATE_PATTERNS:
        for m in pat.finditer(line):
            parts = m.groups()
            if len(parts[0]) == 4:
                iso = _try_date(parts[2], parts[1], parts[0])
                if iso:
                    out.append((iso, True))
            else:
                a, b, c = parts
                iso = _try_date(a, b, c)
                if iso:
                    out.append((iso, True))
                    continue
                iso2 = _try_date(b, a, c)
                if iso2:
                    out.append((iso2, True))
                    continue
                # Lenient: try digit corrections on each part
                found = None
                for aa in _lenient_fix(a):
                    for bb in _lenient_fix(b):
                        for cc in _lenient_fix(c, is_year=True):
                            iso3 = _try_date(aa, bb, cc)
                            if iso3:
                                found = iso3
                                break
                        if found:
                            break
                    if found:
                        break
                if found:
                    out.append((found, False))
    return out


def extract_date(text):
    lines = text.splitlines()
    best = None  # (score, line_idx, iso)
    for i, line in enumerate(lines):
        line_up = line.upper()
        has_label = bool(DATE_LABEL_RE.search(line_up))
        has_time_token = ***REDACTED***"\b\d{1,2}:\d{2}\b", line))
        in_header = i < max(20, len(lines) // 2)

        for iso, strict in find_dates_in_line(line):
            score = 0
            if has_label:
                score += 100
                if re.search(r"\bDATE\b", line_up):
                    score += 20
            if has_time_token:
                score += 30
            if in_header:
                score += 15
            if not strict:
                score -= 50
            score += max(0, 10 - i)
            if best is None or score > best[0]:
                best = (score, i, iso)
    return best[2] if best else None


# ---------------- Total extraction ----------------
def _parse_money(s):
    if s is None:
        return None
    s = s.strip().replace(",", "")
    s = re.sub(r"(\d)[:;](\d{2})\b", r"\1.\2", s)
    m = re.search(r"(\d+)(?:\.(\d{1,2}))?$", s)
    if not m:
        return None
    whole, frac = m.group(1), (m.group(2) or "00").ljust(2, "0")
    return f"{int(whole)}.{frac[:2]}"


def _amounts_in_line(line):
    return [m.group(0) for m in MONEY_RE.finditer(line)]


def _is_excluded(line_up):
    for kw in EXCLUDE_KEYWORDS:
        if kw in line_up:
            return True
    return False


def _match_priority(line_up):
    for prio, patterns in TOTAL_KEYWORDS_PRIORITIZED:
        for pat in patterns:
            if re.search(pat, line_up):
                return prio
    return 0


def extract_total_candidates(text):
    """Return list of (priority, line_idx, amount_str, num_amounts_in_line)."""
    cands = []
    lines = text.splitlines()
    norm_lines = [normalize_number_spaces(l) for l in lines]

    for i, line in enumerate(norm_lines):
        line_up = line.upper()
        if not line_up.strip():
            continue

        inclusive_gst = bool(re.search(r"INCL.*GST|INCLUSIVE.*GST|INCL\.\s*OF\s*GST|INCL\.\s*GST", line_up))
        if _is_excluded(line_up) and not inclusive_gst:
            continue

        prio = _match_priority(line_up)
        if prio == 0:
            continue

        amts = _amounts_in_line(line)
        if amts:
            # Pick last positive amount (skip negatives like '-1.20')
            # Filter out tiny leading numbers if line has 2+ amounts (tax-summary pattern)
            amt = _parse_money(amts[-1])
            if amt:
                cands.append((prio, i, amt, len(amts)))
        else:
            # Split-line fallback: only if next line has ONE amount and NO keyword
            # of its own (avoid picking up "Amount Paid" as a continuation).
            for j in range(i + 1, min(i + 3, len(norm_lines))):
                nxt = norm_lines[j]
                nxt_up = nxt.upper()
                if not nxt.strip():
                    continue
                if _is_excluded(nxt_up):
                    break
                if _match_priority(nxt_up) != 0:
                    # Different labeled line; do not use as continuation
                    break
                amts2 = _amounts_in_line(nxt)
                if amts2:
                    amt = _parse_money(amts2[-1])
                    if amt:
                        cands.append((prio, i, amt, 1))
                    break
    return cands


def extract_total(text):
    cands = extract_total_candidates(text)
    if not cands:
        return None
    max_prio = max(c[0] for c in cands)
