                if prev is None or score > prev[0]:
                    scored[iso] = (score, i)
    if not scored:
        return None
    # Pick date with highest score
    return max(scored.items(), key=lambda kv: kv[1][0])[0]


def process_image(path):
    img = Image.open(path)
    texts = ocr_passes(img)
    date = best_date_from_passes(texts)
    total = best_total_from_passes(texts)
    return date, total


def main():
    files = sorted(IMG_DIR.iterdir())
    files = [f for f in files
             if f.suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".bmp", ".gif", ".tif", ".tiff"}]

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

