def find_dates_in_line(line):
    out = []
    # Textual month format
    for m in MONTH_DATE_RE.finditer(line):
        d, mon_str, y = m.group(1), m.group(2), m.group(3)
        iso = _try_date(d, MONTHS[mon_str.lower()], y)
        if iso:
            out.append((iso, True))
    for pat in DATE_PATTERNS:
        for m in pat.finditer(line):
            parts = m.groups()
            if len(parts[0]) == 4:
                iso = _try_date(parts[2], parts[1], parts[0])
                if iso:
                    out.append((iso, True))
            else:
                a, b, c = parts
                iso = _try_date(a, b, c)
                if iso:
                    out.append((iso, True))
                    continue
                iso2 = _try_date(b, a, c)
                if iso2:
                    out.append((iso2, True))
                    continue
                # Lenient: try digit corrections on each part
                found = None
                for aa in _lenient_fix(a):
                    for bb in _lenient_fix(b):
                        for cc in _lenient_fix(c, is_year=True):
                            iso3 = _try_date(aa, bb, cc)
                            if iso3:
                                found = iso3
                                break
                        if found:
                            break
                    if found:
                        break
                if found:
                    out.append((found, False))
    return out


def extract_date(text):
    lines = text.splitlines()
    best = None  # (score, line_idx, iso)
    for i, line in enumerate(lines):
        line_up = line.upper()
        has_label = bool(DATE_LABEL_RE.search(line_up))
        has_time_token = ***REDACTED***"\b\d{1,2}:\d{2}\b", line))
        in_header = i < max(20, len(lines) // 2)

        for iso, strict in find_dates_in_line(line):
            score = 0
            if has_label:
                score += 100
                if re.search(r"\bDATE\b", line_up):
                    score += 20
            if has_time_token:
                score += 30
            if in_header:
                score += 15
            if not strict:
                score -= 50
            score += max(0, 10 - i)
            if best is None or score > best[0]:
                best = (score, i, iso)
    return best[2] if best else None


# ---------------- Total extraction ----------------
def _parse_money(s):
    if s is None:
        return None
    s = s.strip().replace(",", "")
    s = re.sub(r"(\d)[:;](\d{2})\b", r"\1.\2", s)
    m = re.search(r"(\d+)(?:\.(\d{1,2}))?$", s)
    if not m:
        return None
    whole, frac = m.group(1), (m.group(2) or "00").ljust(2, "0")
    return f"{int(whole)}.{frac[:2]}"


def _amounts_in_line(line):
    return [m.group(0) for m in MONEY_RE.finditer(line)]


def _is_excluded(line_up):
    for kw in EXCLUDE_KEYWORDS:
        if kw in line_up:
            return True
    return False


def _match_priority(line_up):
    for prio, patterns in TOTAL_KEYWORDS_PRIORITIZED:
        for pat in patterns:
            if re.search(pat, line_up):
                return prio
    return 0


def extract_total_candidates(text):
    """Return list of (priority, line_idx, amount_str, num_amounts_in_line)."""
    cands = []
    lines = text.splitlines()
    norm_lines = [normalize_number_spaces(l) for l in lines]

    for i, line in enumerate(norm_lines):
        line_up = line.upper()
        if not line_up.strip():
            continue

        inclusive_gst = bool(re.search(r"INCL.*GST|INCLUSIVE.*GST|INCL\.\s*OF\s*GST|INCL\.\s*GST", line_up))
        if _is_excluded(line_up) and not inclusive_gst:
            continue

        prio = _match_priority(line_up)
        if prio == 0:
            continue

        amts = _amounts_in_line(line)
        if amts:
            # Pick last positive amount (skip negatives like '-1.20')
            # Filter out tiny leading numbers if line has 2+ amounts (tax-summary pattern)
            amt = _parse_money(amts[-1])
            if amt:
                cands.append((prio, i, amt, len(amts)))
        else:
            # Split-line fallback: only if next line has ONE amount and NO keyword
            # of its own (avoid picking up "Amount Paid" as a continuation).
            for j in range(i + 1, min(i + 3, len(norm_lines))):
                nxt = norm_lines[j]
                nxt_up = nxt.upper()
                if not nxt.strip():
                    continue
                if _is_excluded(nxt_up):
                    break
                if _match_priority(nxt_up) != 0:
                    # Different labeled line; do not use as continuation
                    break
                amts2 = _amounts_in_line(nxt)
                if amts2:
                    amt = _parse_money(amts2[-1])
                    if amt:
                        cands.append((prio, i, amt, 1))
                    break
    return cands


def extract_total(text):
    cands = extract_total_candidates(text)
    if not cands:
        return None
    max_prio = max(c[0] for c in cands)
    top = [c for c in cands if c[0] == max_prio]
    # Prefer single-amount lines (clean "label: amount" pattern over summary rows)
    single = [c for c in top if c[3] == 1]
    pool = single if single else top
    # Tie-break by LAST occurrence (rounded totals appear after unrounded)
    pool.sort(key=lambda c: c[1])
    return pool[-1][2]


# ---------------- Per-image pipeline ----------------
def best_from_passes(texts, extractor):
    vals = [v for _, t in texts if (v := extractor(t)) is not None]
    if not vals:
        return None
    return Counter(vals).most_common(1)[0][0]


def best_total_from_passes(texts):
    """Collect every candidate from every pass, then choose globally."""
    all_cands = []
    for _, t in texts:
        all_cands.extend(extract_total_candidates(t))
    if not all_cands:
        return None
    max_prio = max(c[0] for c in all_cands)
    top = [c for c in all_cands if c[0] == max_prio]
    single = [c for c in top if c[3] == 1]
    pool = single if single else top
    # Majority vote on amount; tie by most common, then by last (higher line idx)
    counter = Counter(c[2] for c in pool)
    top_count = counter.most_common(1)[0][1]
    winners = {amt for amt, cnt in counter.items() if cnt == top_count}
    # If a tie, prefer the amount that appears on the highest line index
    best_amt, best_idx = None, -1
    for p, i, amt, n in pool:
        if amt in winners and i > best_idx:
            best_idx, best_amt = i, amt
    return best_amt


def best_date_from_passes(texts):
    """Across passes: for each date, sum its max score; pick the best."""
    scored = {}  # iso -> (best_score, line_idx)
    for _, text in texts:
        lines = text.splitlines()
        for i, line in enumerate(lines):
            line_up = line.upper()
            has_label = bool(DATE_LABEL_RE.search(line_up))
            has_time_token = ***REDACTED***"\b\d{1,2}:\d{2}\b", line))
            in_header = i < max(20, len(lines) // 2)
            for iso, strict in find_dates_in_line(line):
                score = 0
                if has_label:
                    score += 100
                    if re.search(r"\bDATE\b", line_up):
                        score += 20
                if has_time_token:
                    score += 30
                if in_header:
                    score += 15
                if not strict:
                    score -= 50
                score += max(0, 10 - i)
                prev = scored.get(iso)
                if prev is None or score > prev[0]:
                    scored[iso] = (score, i)
    if not scored:
        return None
    # Pick date with highest score
    return max(scored.items(), key=lambda kv: kv[1][0])[0]


def process_image(path):
    img = Image.open(path)
    texts = ocr_passes(img)
    date = best_date_from_passes(texts)
    total = best_total_from_passes(texts)
    return date, total


def main():
    files = sorted(IMG_DIR.iterdir())
    files = [f for f in files
             if f.suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".bmp", ".gif", ".tif", ".tiff"}]

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for f in files:
        print(f"Processing {f.name}...", file=sys.stderr)
        try:
            date, total = process_image(f)
        except Exception as e:
            print(f"  ERROR: {e}", file=sys.stderr)
            date, total = None, None
        print(f"  -> date={date}, total={total}", file=sys.stderr)
        ws.append([f.name, date, total])

    wb.save(OUT_XLSX)
    print(f"Wrote {OUT_XLSX}", file=sys.stderr)


if __name__ == "__main__":
    main()
