def _try_date(d, m, y):
    try:
        d, m, y = int(d), int(m), int(y)
    except (ValueError, TypeError):
        return None
    if y < 100:
        y += 2000 if y < 50 else 1900
    if not (1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2030):
        return None
    try:
        datetime.date(y, m, d)
    except ValueError:
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


