                found = None
                for aa in _lenient_fix(a):
                    for bb in _lenient_fix(b):
                        for cc in _lenient_fix(c, is_year=True):
                            iso3 = _try_date(aa, bb, cc)
                            if iso3:
                                found = iso3
                                break
                        if found:
                            break
                    if found:
                        break
                if found:
                    out.append((found, False))
    return out


def extract_date(text):
    lines = text.splitlines()
    best = None  # (score, line_idx, iso)
    for i, line in enumerate(lines):
        line_up = line.upper()
        has_label = bool(DATE_LABEL_RE.search(line_up))
        has_time_token = ***REDACTED***"\b\d{1,2}:\d{2}\b", line))
        in_header = i < max(20, len(lines) // 2)

        for iso, strict in find_dates_in_line(line):
            score = 0
            if has_label:
                score += 100
                if re.search(r"\bDATE\b", line_up):
                    score += 20
            if has_time_token:
                score += 30
            if in_header:
                score += 15
            if not strict:
                score -= 50
            score += max(0, 10 - i)
            if best is None or score > best[0]:
                best = (score, i, iso)
    return best[2] if best else None


# ---------------- Total extraction ----------------
def _parse_money(s):
    if s is None:
        return None
    s = s.strip().replace(",", "")
    s = re.sub(r"(\d)[:;](\d{2})\b", r"\1.\2", s)
    m = re.search(r"(\d+)(?:\.(\d{1,2}))?$", s)
    if not m:
        return None
    whole, frac = m.group(1), (m.group(2) or "00").ljust(2, "0")
    return f"{int(whole)}.{frac[:2]}"


def _amounts_in_line(line):
    return [m.group(0) for m in MONEY_RE.finditer(line)]


def _is_excluded(line_up):
    for kw in EXCLUDE_KEYWORDS:
        if kw in line_up:
            return True
    return False


def _match_priority(line_up):
    for prio, patterns in TOTAL_KEYWORDS_PRIORITIZED:
        for pat in patterns:
            if re.search(pat, line_up):
                return prio
